<?php

namespace seo;

/**
 * Одноразовая публикация FAQ товаров (07.11.2026). Пишет только в пустые
 * поля «Частые вопросы» товаров. Инструменты → «FAQ товаров». После запуска
 * файл удаляется из темы.
 */
class ProductFaqImport
{
    private static function data(): array
    {
        return json_decode(<<<'JSON'
{"zhytomyr-3": [{"question": "Нужно ли котлу Житомир-3 электричество?", "answer": "<p>Нет. Котёл энергонезависимый: розжиг пьезоэлектрический, автоматика безопасности SIT работает без подключения к сети. Отопление не остановится, если отключат свет.</p>"}, {"question": "Какую площадь отопит Житомир-3?", "answer": "<p>Зависит от модификации: от 70 м² у модели на 7 кВт до 400 м² у модели на 40 кВт. Таблица мощностей и площадей — на странице товара в блоке «Модификации».</p>"}, {"question": "Чем КС-Г отличается от КС-ГВ?", "answer": "<p>КС-Г — одноконтурный котёл, только отопление. КС-ГВ — двухконтурный: в нём медный змеевик для горячей воды производительностью от 175 кг/ч (7 кВт) при нагреве на 35 °С.</p>"}, {"question": "Можно ли поставить в Житомир-3 электрический ТЭН?", "answer": "<p>Да, в модели от 10 до 16 кВт. Готовая версия с установленным ТЭНом — Житомир-3 с ТЭНом.</p>"}, {"question": "Какой КПД у котла?", "answer": "<p>До 97% по таблице характеристик.</p>"}], "zhytomyr-3-with-teno": [{"question": "Как работает котёл с ТЭНом?", "answer": "<p>Основной режим — газ, как у обычного Житомир-3. Установленный электрический ТЭН с блоком управления — резервный источник тепла: им можно поддерживать отопление без газа.</p>"}, {"question": "Нужно ли подключение к электросети?", "answer": "<p>Да, ТЭНу и блоку управления нужна сеть 220 В. Газовая часть котла работает и без электричества.</p>"}, {"question": "Какие мощности есть?", "answer": "<p>10 кВт (до 100 м²) и 12,5 кВт (до 125 м²), в одноконтурном (КС-Г) и двухконтурном (КС-ГВ) исполнении.</p>"}], "zhytomyr-10": [{"question": "Чем Житомир-10 отличается от Житомир-3?", "answer": "<p>В одном корпусе — газовый котёл и газовая колонка на 18 кВт. Отопление и горячая вода работают независимо, при этом у котла одно подключение газа и один выход в дымоход.</p>"}, {"question": "Сколько горячей воды даёт колонка?", "answer": "<p>До 10 литров в минуту.</p>"}, {"question": "Нужно ли электричество?", "answer": "<p>Нет, котёл не требует подключения к электросети.</p>"}, {"question": "Какую площадь отопит?", "answer": "<p>От 70 м² (7 кВт) до 320 м² (31,5 кВт).</p>"}], "zhytomyr-turbo": [{"question": "Нужен ли Житомир-Турбо дымоход?", "answer": "<p>Классический дымоход не нужен: вентилятор принудительно выводит продукты сгорания через наружную стену по коаксиальной трубе.</p>"}, {"question": "Нужно ли электричество?", "answer": "<p>Да, для работы вентилятора котёл подключается к сети 220 В. Потребляемая мощность — до 75 Вт.</p>"}, {"question": "Какая автоматика стоит?", "answer": "<p>Газовый клапан SIT 820 NOVA, который обычно ставят на котлы премиум-класса.</p>"}, {"question": "Какую площадь отопит?", "answer": "<p>От 100 м² (10 кВт) до 400 м² (40 кВт). Есть модели с нагревом воды (КС-ГВ).</p>"}], "zhytomyr-m": [{"question": "Можно ли поставить Житомир-М в квартиру?", "answer": "<p>Да. Камера сгорания герметичная, воздух забирается и продукты сгорания отводятся через наружную стену, поэтому котёл подходит для многоквартирных домов.</p>"}, {"question": "Нужен ли дымоход?", "answer": "<p>Нет. Котёл парапетного типа выводит газы через дымовоздушный блок в стене.</p>"}, {"question": "Нужно ли электричество?", "answer": "<p>Нет, котёл энергонезависимый.</p>"}, {"question": "Чем АОГВ отличается от АДГВ?", "answer": "<p>АОГВ — одноконтурный, только отопление. АДГВ — двухконтурный, нагревает воду: от 2,6 л/мин (7 кВт) до 5,7 л/мин (15 кВт).</p>"}], "zhytomyr-9": [{"question": "Можно ли топить одновременно газом и дровами?", "answer": "<p>Да. В котле два независимых блока отопления, при необходимости они работают одновременно.</p>"}, {"question": "Какой КПД на газе и на твёрдом топливе?", "answer": "<p>До 97% на газе и до 78% на твёрдом топливе.</p>"}, {"question": "Нужно ли электричество?", "answer": "<p>Нет, котёл не требует подключения к сети.</p>"}, {"question": "Есть ли нагрев воды?", "answer": "<p>Да, у моделей КС-ГВ.</p>"}], "zhytomyr-aotv-aktv": [{"question": "Какую площадь отопит котёл?", "answer": "<p>14 кВт — до 140 м², 18 кВт — до 180 м², 22 кВт — до 220 м².</p>"}, {"question": "Сколько угля расходует котёл?", "answer": "<p>По антрациту — от 2,2 кг/ч (14 кВт) до 3,5 кг/ч (22 кВт) на номинальной мощности.</p>"}, {"question": "Есть ли нагрев воды?", "answer": "<p>Да, у моделей с индексом «В» (АОТВ-14В, АКТВ-18В и т. д.).</p>"}, {"question": "Можно ли установить электрический ТЭН?", "answer": "<p>Да, котёл подготовлен под ТЭН «Атем Электрорезерв».</p>"}], "zhytomyr": [{"question": "Какие модели есть?", "answer": "<p>Житомир-14М, 18М и 22М — на 14, 18 и 22 кВт, для домов до 140, 180 и 220 м².</p>"}, {"question": "Нужно ли электричество?", "answer": "<p>Нет, котёл работает без подключения к сети.</p>"}, {"question": "Можно ли подогревать воду?", "answer": "<p>Нет, у этой серии нет контура ГВС. Если он нужен, смотрите модели АОТВ/АКТВ с индексом «В».</p>"}], "zhytomyr-5": [{"question": "Можно ли подключить конвектор к баллону?", "answer": "<p>Да. Конвектор поставляется под сжиженный газ, комплект для перехода на природный газ — в комплекте.</p>"}, {"question": "Нужно ли электричество?", "answer": "<p>Нет. Розжиг пьезоэлектрический, газовый клапан 630 Eurosit работает без сети.</p>"}, {"question": "Чем Житомир-5 лучше обычного КНС?", "answer": "<p>Площадь теплоотдачи увеличена вдвое, теплообменник стальной, корпус цельносварной. Поэтому конвектор быстрее прогревает помещение и экономичнее.</p>"}], "hsv-20": [{"question": "Сколько горячей воды даёт колонка?", "answer": "<p>До 9,3 л/мин при нагреве на 25 °С и до 6,8 л/мин при нагреве на 40 °С.</p>"}, {"question": "Нужна ли розетка?", "answer": "<p>Нет. Розжиг от батареек типа D.</p>"}, {"question": "При каком давлении воды работает?", "answer": "<p>От 0,05 МПа. Есть защита от «сухого» горения, перегрева и высокого давления, контроль тяги.</p>"}, {"question": "Какая гарантия?", "answer": "<p>2 года.</p>"}], "hsv-20m": [{"question": "Сколько горячей воды даёт колонка?", "answer": "<p>До 10 л/мин при нагреве на 25 °С и до 7,2 л/мин при нагреве на 40 °С.</p>"}, {"question": "Нужна ли розетка?", "answer": "<p>Нет, розжиг от батареек типа D.</p>"}, {"question": "Нужен ли дымоход?", "answer": "<p>Да, колонка дымоходная, диаметр патрубка — 100 мм.</p>"}], "hsv-20tm": [{"question": "Что значит «модуляционная»?", "answer": "<p>Колонка сама подстраивает пламя под расход воды, поэтому температура держится ровнее при изменении напора.</p>"}, {"question": "Сколько горячей воды даёт?", "answer": "<p>До 10 литров в минуту.</p>"}, {"question": "Какая мощность у ВПГ-20ТМ?", "answer": "<p>Тепловая мощность горелки — 22,4 кВт. Есть защита от «сухого» горения, перегрева и высокого давления, контроль тяги; колонка работает при низком давлении воды.</p>"}], "vpg-20t": [{"question": "Нужен ли дымоход?", "answer": "<p>Нет. Колонка турбированная: продукты сгорания выводятся через стену по коаксиальной трубе длиной 880 мм из комплекта.</p>"}, {"question": "Нужна ли розетка?", "answer": "<p>Да, турбине нужно подключение к сети 220 В.</p>"}, {"question": "Работает ли при слабом напоре?", "answer": "<p>Да, от 0,01 МПа. Есть защита от замерзания.</p>"}, {"question": "Сколько горячей воды даёт?", "answer": "<p>9,4 л/мин.</p>"}]}
JSON, true) ?: [];
    }

    public static function register(): void
    {
        add_action('admin_menu', static function () {
            add_management_page('FAQ товаров', 'FAQ товаров', 'manage_options', 'gkb-import-pfaq', [self::class, 'page']);
        });
    }

    public static function page(): void
    {
        if (!current_user_can('manage_options')) {
            return;
        }
        $log = [];
        if (isset($_POST['gkb_import']) && check_admin_referer('gkb_import_pfaq')) {
            foreach (self::data() as $slug => $rows) {
                $post = get_page_by_path($slug, OBJECT, 'products');
                if (!$post) {
                    $log[] = "$slug: товар не найден";
                    continue;
                }
                if (array_filter((array) get_field('faq', $post->ID))) {
                    $log[] = "$slug: уже заполнено, пропущено";
                    continue;
                }
                update_field('faq', $rows, $post->ID);
                $log[] = "$slug: " . count($rows);
            }
        }
        echo '<div class="wrap"><h1>FAQ товаров</h1>';
        if ($log) {
            echo '<div class="notice notice-success"><p>' . esc_html(implode('; ', $log)) . '</p></div>';
        }
        echo '<table class="widefat striped"><thead><tr><th>Товар</th><th>Вопросов в черновике</th><th>Сейчас в поле</th></tr></thead><tbody>';
        foreach (self::data() as $slug => $rows) {
            $post = get_page_by_path($slug, OBJECT, 'products');
            echo '<tr><td>' . esc_html($post ? get_the_title($post) . ' (' . $slug . ')' : $slug . ' — не найден') . '</td><td>' . count($rows) . '</td><td>'
                . ($post ? count(array_filter((array) get_field('faq', $post->ID))) : 0) . '</td></tr>';
        }
        echo '</tbody></table><form method="post" style="margin-top:16px">';
        wp_nonce_field('gkb_import_pfaq');
        echo '<button class="button button-primary" name="gkb_import" value="1">Заполнить пустые</button></form></div>';
    }
}
